parameters.jsCode:
const order = $input.first().json;

// Generate nomor surat jalan: SJ/YYYYMMDD/XXX
const now = new Date();
const dateStr = now.getFullYear().toString() +
  String(now.getMonth() + 1).padStart(2, '0') +
  String(now.getDate()).padStart(2, '0');
const seq = String(Math.floor(Math.random() * 999) + 1).padStart(3, '0');
const nomorSJ = `SJ/${dateStr}/${seq}`;

// Format items table
const items = (order.items || []).map((item, i) => ({
  no: i + 1,
  kode_barang: item.sku || item.kode || '-',
  nama_barang: item.nama || item.name || '-',
  satuan: item.satuan || item.unit || 'pcs',
  jumlah: item.qty || item.jumlah || 0,
  keterangan: item.keterangan || item.notes || ''
}));

const totalBarang = items.reduce((sum, i) => sum + Number(i.jumlah), 0);

return [{
  json: {
    nomor_surat_jalan: nomorSJ,
    tanggal: now.toLocaleDateString('id-ID', {day: '2-digit', month: 'long', year: 'numeric'}),
    nomor_po: order.po_number || order.nomor_po || '-',

    pengirim_nama: order.pengirim?.nama || order.sender_name || 'PT. Nama Perusahaan',
    pengirim_alamat: order.pengirim?.alamat || order.sender_address || 'Jl. Sudirman No.1, Jakarta',
    pengirim_telepon: order.pengirim?.telepon || order.sender_phone || '-',

    penerima_nama: order.penerima?.nama || order.recipient_name || '-',
    penerima_alamat: order.penerima?.alamat || order.recipient_address || '-',
    penerima_telepon: order.penerima?.telepon || order.recipient_phone || '-',
    penerima_kota: order.penerima?.kota || order.recipient_city || '-',

    ekspedisi: order.ekspedisi || order.courier || '-',
    no_resi: order.no_resi || order.tracking_number || 'Akan diisi',

    items: items,
    total_barang: totalBarang,
    catatan: order.catatan || order.notes || ''
  }
}];

